[
    DataContractAttribute
]
class AVATraverseRegalvanizationContract  //implements SysOperationValidatable, SysOperationInitializable
{
    Prodid          contractProdId;
    AVATravNum      contractTravNum;
    Qty             contractQty;
    ProdParmId      prodParmId;

}

Method.Source:
public prodParmId parmReportFinishedParmId(prodParmId _parmValue = prodParmId)
{
    prodParmId = _parmValue;

    return prodParmId;
}

public ProdId parmProdId(ProdId _parmValue = contractProdId)
{
    contractProdId = _parmValue;

    return contractProdId;
}

public AVATravNum parmTraverseNum(AVATravNum _parmValue = contractTravNum)
{
    contractTravNum = _parmValue;

    return contractTravNum;
}

[
    DataMemberAttribute('Qty'),
    sysoperationlabelattribute("@NDX:NXATravZQty")
]
public Qty parmQty(qty _parmValue = contractQty)
{
    contractQty = _parmValue;

    return contractQty;
}
